export const PublishListingBody = zod.object({
  sessionId: zod.number(),
  title: zod.string(),
  category: zod.string(),
  description: zod.string(),
  listingPrice: zod.number(),
});

/**
 * @summary Get a marketplace listing detail with embedded design output
 */
export const GetMarketplaceListingParams = zod.object({
  id: zod.coerce.number(),
});

export const GetMarketplaceListingResponse = zod.object({
  id: zod.number(),
  sessionId: zod.number(),
  userId: zod.string(),
  creatorHandle: zod.string(),
  title: zod.string(),
  category: zod.string(),
  description: zod.string(),
  listingPrice: zod.number(),
  orderCount: zod.number(),
  designOutput: zod.object({
    id: zod.number(),
    sessionId: zod.number(),
    productName: zod.string(),
    category: zod.string(),
    summary: zod.string(),
    primaryMaterial: zod.string(),
    materials: zod.array(zod.string()),
    dimensions: zod.string(),
    weightGrams: zod.number().nullish(),
    processes: zod.array(zod.string()),
    bom: zod.array(
      zod.object({
        component: zod.string(),
        material: zod.string(),
        quantity: zod.number(),
        unit: zod.string(),
        unitCost: zod.number(),
        totalCost: zod.number(),
      }),
    ),
    costEstimate: zod.object({
      low: zod.number(),
      high: zod.number(),
      currency: zod.string(),
      leadTimeDays: zod.number(),
    }),
    imageUrl: zod
      .string()
      .nullish()
      .describe("URL to a hosted image (object storage URL or null)"),
    manufacturingNotes: zod.string(),
    createdAt: zod.coerce.date(),
  }),
  quotes: zod.array(
    zod.object({
      id: zod.number(),
      sessionId: zod.number(),
      supplier: zod.object({
        id: zod.number(),
        slug: zod.string(),
        name: zod.string(),
        tagline: zod.string(),
        description: zod.string(),
        location: zod.string(),
        country: zod.string(),
        capabilities: zod.array(zod.string()),
        materials: zod.array(zod.string()),
        certifications: zod.array(zod.string()),
        leadTimeMinDays: zod.number(),
        leadTimeMaxDays: zod.number(),
        pricingMultiplier: zod.number(),
        setupFee: zod.number(),
        rating: zod.number(),
        capacityLevel: zod.enum(["low", "medium", "high"]),
      }),
      unitCost: zod.number(),
      setupFee: zod.number(),
      totalCost: zod.number(),
      leadTimeDays: zod.number(),
      processBreakdown: zod.array(
        zod.object({
          process: zod.string(),
          description: zod.string(),
          cost: zod.number(),
        }),
      ),
      scoreFactors: zod.object({
        processMatch: zod.number(),
        materialMatch: zod.number(),
        leadTime: zod.number(),
        rating: zod.number(),
        total: zod.number(),
      }),
      rank: zod.number(),
      notes: zod.string(),
      createdAt: zod.coerce.date(),
    }),
  ),
  createdAt: zod.coerce.date(),
  updatedAt: zod.coerce.date(),
});

